import pandas as pd, os
# Quick load of all available experiments
for fname in ["experiment_1","experiment_2","experiment_3","experiment_5","experiment_7","experiment_9","experiment_10","experiment_12","experiment_13"]:
    var = globals()[fname + "_csv"]
    if os.path.exists(var):
        try:
            df = pd.read_csv(var)
            print(f"\n--- {fname}: {len(df)} rows ---")
            print(df.columns.tolist())
            print(df.head(2).to_string())
            # Check for temperature and conversion columns
            t_cols = [c for c in df.columns if 'temp' in c.lower()]
            c_cols = [c for c in df.columns if 'conv' in c.lower() or 'eff' in c.lower()]
            if t_cols: print(f"  Temp cols: {t_cols} -> {df[t_cols[0]].describe()}")
            if c_cols: print(f"  Conv cols: {c_cols} -> {df[c_cols[0]].describe()}")
        except Exception as e:
            print(f"  Error: {e}")
